                    missing.add(gate)
            if any(value is None for value in bindings.values()):
                missing.add("complete_source_bindings")
            if any(value is None for value in intents.values()):
                missing.add("complete_producer_intent")
            inspection = {
                "scope": "request_and_frozen_family_metadata_only",
                "registration_profile": request["registration_profile"],
                "family_sha256": request["family_sha256"],
                "comparison_ids": [item["comparison_id"] for item in family["comparisons"]],
                "source_keys": keys,
                "consumer_file_count": len(consumers),
                "source_admission_granted": False,
                "runtime_admission_granted": False,
                "complete_execution_inventory_verified": False,
            }
